#!/usr/bin/env python3
"""Turn `tsci convert` output (one TSX per .kicad_mod) into a single module of
reusable <footprint> elements: hardware/lib/kicad-footprints.tsx.

usage: tools/import_kicad_footprints.py <dir with converted .tsx> <out.tsx>
"""
import re
import sys
from pathlib import Path

src, out = Path(sys.argv[1]), Path(sys.argv[2])
parts = ["// Generated by tools/import_kicad_footprints.py from KiCad library",
         "// footprints (CC-BY-SA 4.0 with exception, gitlab.com/kicad/libraries).",
         "// Do not edit by hand; re-run the script instead.", ""]
for f in sorted(src.glob("*.tsx")):
    t = f.read_text()
    m = re.search(r"footprint=\{(<footprint>.*?</footprint>)\}", t, re.S)
    if not m:
        print("skip", f.name)
        continue
    body = m.group(1)
    # drop reference/value placeholder texts and fab-layer clutter
    body = "\n".join(
        l for l in body.splitlines()
        if "REF**" not in l and "fabricationnote" not in l
    )
    ident = "FP_" + re.sub(r"[^0-9A-Za-z]+", "_", f.stem).strip("_")
    parts.append(f"export const {ident} = (\n  {body.strip()}\n)\n")
out.write_text("\n".join(parts))
print("wrote", out)
